1. Fenêtre de recherche :
```
seed@seed:~$ cd ~/lab/task2
seed@seed:~/lab/task2$ cat bob_notes.txt
seed@seed:~/lab/task2$ END=$(date -u -d "DATE DE CRÉATION" +%s); START=$((END-7200))
```

2. Programme de force brute `brute.c` :
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>

#define KEYSIZE 16

static void hex2bin(const char *hex, unsigned char *out)
{
    for (int i = 0; i < 16; i++) {
        unsigned int byte;
        sscanf(hex + 2 * i, "%2x", &byte);
        out[i] = (unsigned char)byte;
    }
}

int main(int argc, char *argv[])
{
    if (argc != 6) {
        fprintf(stderr, "usage: %s START END PLAINTEXT CIPHERTEXT IV\n", argv[0]);
        return 1;
    }
    long start = atol(argv[1]), end = atol(argv[2]);
    unsigned char pt[16], ct[16], iv[16], key[KEYSIZE], out[32];
    int len;
    hex2bin(argv[3], pt);
    hex2bin(argv[4], ct);
    hex2bin(argv[5], iv);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    for (long t = start; t <= end; t++) {
        srand(t);                                  /* même graine que keygen.c */
        for (int i = 0; i < KEYSIZE; i++)
            key[i] = rand() % 256;                 /* même clé que keygen.c */
        EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv);
        EVP_CIPHER_CTX_set_padding(ctx, 0);        /* un seul bloc, pas de padding */
        EVP_EncryptUpdate(ctx, out, &len, pt, 16);
        if (memcmp(out, ct, 16) == 0) {
            printf("Graine trouvée : %ld\nClé : ", t);
            for (int i = 0; i < KEYSIZE; i++)
                printf("%.2x", key[i]);
            printf("\n");
            EVP_CIPHER_CTX_free(ctx);
            return 0;
        }
    }
    EVP_CIPHER_CTX_free(ctx);
    printf("Clé non trouvée dans la fenêtre\n");
    return 1;
}
```

3. Compilation, recherche et déchiffrement :
```
seed@seed:~/lab/task2$ gcc brute.c -o brute -lcrypto
seed@seed:~/lab/task2$ ./brute $START $END 255044462d312e350a25d0d4c5d80a34 CIPHERTEXT IV
Graine trouvée : ...
Clé : CLE
seed@seed:~/lab/task2$ openssl enc -d -aes-128-cbc -K CLE -iv IV -in alice_tax_return.pdf.enc -out alice.pdf
seed@seed:~/lab/task2$ strings alice.pdf | grep -i flag
(Flag de la tache 2 : ${ANSWER}) Tj ET
```

**Explication.** La clé ne dépend que de la graine `time()`. Une fenêtre de 2 heures ne contient que 7 201 graines, donc 7 201 clés possibles (au lieu de 2^128) : la recherche prend moins d'une seconde.

Le flag est **`${ANSWER}`**.

hints.content:
Pour chaque graine `t` de la fenêtre :
1. `srand(t)` puis 16 fois `key[i] = rand() % 256` (exactement comme `keygen.c`) ;
2. chiffrer le bloc clair connu en AES-128-CBC avec cette clé et l'IV de Bob, **sans padding** ;
3. si le résultat est égal au bloc chiffré connu, la clé est trouvée.

```c
